// Normaliza la aplicacion del VSL, arma la nota para GHL, el aviso de Discord
// y el payload para Meta Conversions API.
const crypto = require('crypto');
const b = $input.first().json.body || {};

const REVENUE_LABEL = {
  '5-10k': '$5,000 - $10,000 / mes',
  '10-20k': '$10,000 - $20,000 / mes',
  '20-40k': '$20,000 - $40,000 / mes',
  '50k+': '$50,000+ / mes'
};

const dash = (v) => (v === undefined || v === null || String(v).trim() === '') ? '-' : String(v).trim();
const yesNo = (v) => v === 'si' ? 'Si' : (v === 'no' ? 'No' : '-');
const sha256 = (v) => v ? crypto.createHash('sha256').update(String(v).trim().toLowerCase()).digest('hex') : undefined;

const parts = String(b.full_name || '').trim().split(/\s+/);
const firstName = parts.shift() || '';
const lastName = parts.join(' ');

const qualified = b.qualified === true || b.qualified === 'true';
const revenue = REVENUE_LABEL[b.monthly_revenue] || dash(b.monthly_revenue);
const email = String(b.email || '').trim().toLowerCase();
const phone = String(b.phone || '').trim();

// Meta quiere el telefono como digitos con codigo de pais, sin '+' ni ceros
// a la izquierda. Asume EE.UU. si vienen 10 digitos.
let phoneDigits = phone.replace(/\D/g, '');
if (phoneDigits.length === 10) phoneDigits = '1' + phoneDigits;

const note = [
  `APLICACION VSL - ${qualified ? 'CALIFICA' : 'NO CALIFICA'}`,
  '',
  `1. Dueno de compania de pintura en EE.UU.: ${yesNo(b.owner_us_painting_company)}`,
  `2. Facturacion mensual: ${revenue}`,
  `3. Licencia y seguro en regla: ${yesNo(b.licensed_insured)}`,
  `4. Area de servicio: ${dash(b.service_area)}`,
  '',
  `Compania: ${dash(b.company)}`,
  `Consentimiento SMS: ${b.sms_consent ? 'Si' : 'No'}`,
  qualified ? null : `Motivo de descalificacion: ${dash(b.disqualified_reason)}`,
  `Enviado: ${b.submitted_at || new Date().toISOString()}`,
  `Pagina: ${dash(b.page)}`
].filter(x => x !== null).join('\n');

// Aviso a Discord con TODOS los datos del formulario, para que ninguna
// aplicacion se pierda aunque GHL falle.
const fields = [
  { name: 'Nombre', value: dash(b.full_name), inline: true },
  { name: 'Compania', value: dash(b.company), inline: true },
  { name: 'Email', value: dash(email), inline: false },
  { name: 'Telefono', value: dash(phone), inline: true },
  { name: 'Consentimiento SMS', value: b.sms_consent ? 'Si' : 'No', inline: true },
  { name: 'Area de servicio', value: dash(b.service_area), inline: false },
  { name: '1. Dueno en EE.UU.', value: yesNo(b.owner_us_painting_company), inline: true },
  { name: '2. Facturacion mensual', value: revenue, inline: true },
  { name: '3. Licencia y seguro', value: yesNo(b.licensed_insured), inline: true }
];

if (!qualified) {
  fields.push({ name: 'Motivo de descalificacion', value: dash(b.disqualified_reason), inline: false });
}

const discord = {
  username: 'Topcoat VSL',
  embeds: [{
    title: qualified ? 'Nueva aplicacion VSL - CALIFICA' : 'Nueva aplicacion VSL - NO CALIFICA',
    color: qualified ? 3066993 : 15158332,
    fields,
    footer: { text: dash(b.page) },
    timestamp: b.submitted_at || new Date().toISOString()
  }]
};

// Payload para Meta Conversions API - evento Lead. em/ph/fn/ln van hasheados
// en SHA-256 (lowercase, sin espacios). fbc/fbp/user_agent van en texto
// plano - Meta los usa para machear con la sesion del navegador.
const eventTime = b.submitted_at ? Math.floor(new Date(b.submitted_at).getTime() / 1000) : Math.floor(Date.now() / 1000);

const metaCapi = {
  data: [{
    event_name: 'Lead',
    event_time: eventTime,
    event_id: b.fb_event_id || undefined,
    event_source_url: b.page || undefined,
    action_source: 'website',
    user_data: {
      em: email ? [sha256(email)] : undefined,
      ph: phoneDigits ? [sha256(phoneDigits)] : undefined,
      fn: firstName ? [sha256(firstName)] : undefined,
      ln: lastName ? [sha256(lastName)] : undefined,
      fbc: b.fbc || undefined,
      fbp: b.fbp || undefined,
      client_user_agent: b.user_agent || undefined
    },
    custom_data: {
      content_name: 'Aplicacion VSL',
      content_category: qualified ? 'calificado' : 'no_calificado'
    }
  }]
};

return [{
  json: {
    firstName,
    lastName,
    email,
    phone,
    companyName: b.company || '',
    qualified,
    tags: ['top-coat-media', 'vsl', qualified ? 'vsl-calificado' : 'vsl-no-calificado'],
    note,
    discord,
    metaCapi
  }
}];
